	userID     *UserID
	activityID *ActivityID
	subject    *string
	duration   *string
	outcome    *CallLogOutcome
	fromPhone  *string
	toPhone    *string
	startTime  *time.Time
	endTime    *time.Time
	personID   *PersonID
	orgID      *OrganizationID
	dealID     *DealID
	leadID     *LeadID
	note       *string
