func TestFilesService_Upload(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if got := r.Header.Get("X-Test"); got != "1" {
			t.Fatalf("unexpected header X-Test: %q", got)
		}
		if err := r.ParseMultipartForm(1 << 20); err != nil {
			t.Fatalf("parse multipart form: %v", err)
		}
		if got := r.FormValue("deal_id"); got != "42" {
			t.Fatalf("unexpected deal_id: %q", got)
		}
		if got := r.FormValue("lead_id"); got != "adf21080-0e10-11eb-879b-05d71fb426db" {
			t.Fatalf("unexpected lead_id: %q", got)
		}
		part, header, err := r.FormFile("file")
		if err != nil {
			t.Fatalf("form file: %v", err)
		}
		defer part.Close()
		if header.Filename != "report.pdf" {
			t.Fatalf("unexpected filename: %q", header.Filename)
		}
		content, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read file part: %v", err)
		}
		if string(content) != "document body" {
			t.Fatalf("unexpected file content: %q", string(content))
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":21,"file_name":"report.pdf"}}`))
	})

	file, err := client.Files.Upload(
		context.Background(),
		"report.pdf",
		strings.NewReader("document body"),
		WithUploadDealID(DealID(42)),
		WithUploadLeadID(LeadID("adf21080-0e10-11eb-879b-05d71fb426db")),
		WithUploadRequestOptions(pipedrive.WithHeader("X-Test", "1")),
	)
	if err != nil {
		t.Fatalf("Upload error: %v", err)
	}
	if file.ID != 21 || file.FileName != "report.pdf" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func TestFilesService_Upload_RetriesOn429(t *testing.T) {
	t.Parallel()

	var contents []string
	cfg := pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{
			MaxAttempts: 2,
			BaseDelay:   time.Millisecond,
		},
	}
	client := newTestClientWithConfig(t, cfg, func(w http.ResponseWriter, r *http.Request) {
		if err := r.ParseMultipartForm(1 << 20); err != nil {
			t.Errorf("parse multipart form: %v", err)
		}
		part, _, err := r.FormFile("file")
		if err != nil {
			t.Errorf("form file: %v", err)
			return
		}
		defer part.Close()
		content, err := io.ReadAll(part)
		if err != nil {
			t.Errorf("read file part: %v", err)
		}
		contents = append(contents, string(content))
		if len(contents) == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":22,"file_name":"import.csv"}}`))
	})

	// io.MultiReader is not seekable: the buffered multipart body must make
